//! A dependency's completed Build and the product continuation it may require.
//!
//! Build admission checks the code that executes, but does not confer a checked
//! product or review verdict. Generated bytes carry source/output custody into
//! consumers. If an actual independent product is requested, its retained typed
//! continuation proceeds to final checking without executing the Build again.

use crate::{ComputedBuildConfig, PreparedBuild};
use diagnostics::Diagnostic;
use optimization_core::OptimizationRollback;
use package_compilation::{
    IndependentComponentDescription, PackageCompilationInputError, PackageCompilationInputs,
    PackageGeneratedSourceBundle,
};
use std::path::PathBuf;
use target::TargetProfile;

pub struct PreparedPackageBuild {
    root_path: PathBuf,
    target: TargetProfile,
    inputs: PackageCompilationInputs,
    rollback: OptimizationRollback,
    permit_unsettled_fused_service_fields: bool,
    prepared: PreparedBuild,
    generated_sources: PackageGeneratedSourceBundle,
}

impl PreparedPackageBuild {
    /// Compare complete source-completion inputs after each activation has
    /// independently admitted and executed Build. Target stamps, grants and
    /// independent-component descriptions are realization inputs, not source.
    /// Pending typing/evaluation state must match, not merely Build's value.
    pub fn same_product_source(&self, other: &Self) -> bool {
        let build = &self.prepared.built.computed_build_config;
        let other_build = &other.prepared.built.computed_build_config;
        self.root_path == other.root_path
            && self.rollback == other.rollback
            && self.prepared.build_sources == other.prepared.build_sources
            // Execution receipts and charges remain on each activation. They
            // cannot partition source work, nor be replaced by a sibling's.
            && build.config == other_build.config
            && build.selected_build_machine_symbol == other_build.selected_build_machine_symbol
            && build.generated_sources == other_build.generated_sources
            && self.prepared.built.admission.application
                == other.prepared.built.admission.application
            && package_compilation::SourceAssemblyInputs::new(
                Some(&self.inputs),
                self.prepared.build_sources.build_execution_profile,
            ) == package_compilation::SourceAssemblyInputs::new(
                Some(&other.inputs),
                other.prepared.build_sources.build_execution_profile,
            )
            && self.inputs.semantic_role_discovery() == other.inputs.semantic_role_discovery()
            && self
                .inputs
                .accepted_semantic_bindings()
                .eq(other.inputs.accepted_semantic_bindings())
            && self
                .prepared
                .built
                .source
                .same_completion_input(&other.prepared.built.source)
    }

    /// Bind one completed Build to its exact inputs and sealed output bytes.
    #[doc(hidden)]
    pub fn seal(
        root_path: PathBuf,
        target: TargetProfile,
        inputs: PackageCompilationInputs,
        rollback: OptimizationRollback,
        prepared: PreparedBuild,
        permit_unsettled_fused_service_fields: bool,
    ) -> Result<Self, Vec<Diagnostic>> {
        let generated_sources = prepared.build_sources.package_generated_source_bundle(
            prepared.built.source.typed(),
            &inputs,
            target,
            prepared
                .built
                .computed_build_config
                .generated_sources
                .clone(),
        )?;
        Ok(Self {
            root_path,
            target,
            inputs,
            rollback,
            permit_unsettled_fused_service_fields,
            prepared,
            generated_sources,
        })
    }

    pub fn generated_source_bundle(&self) -> &PackageGeneratedSourceBundle {
        &self.generated_sources
    }

    pub fn root_path(&self) -> &std::path::Path {
        &self.root_path
    }

    pub fn build(&self) -> &ComputedBuildConfig {
        &self.prepared.built.computed_build_config
    }

    pub fn package_inputs(&self) -> &PackageCompilationInputs {
        &self.inputs
    }

    pub fn permits_unsettled_fused_service_fields(&self) -> bool {
        self.permit_unsettled_fused_service_fields
    }

    pub fn timings(&self) -> &artifacts::compile_timings::CompileTimings {
        &self.prepared.timings
    }

    /// The Build judgment this occurrence retained for its next equal-input
    /// settlement, when one was requested.
    pub fn retained_build_check(&self) -> Option<&psi_compiler::RetainedCheck> {
        self.prepared.built.retained_build_check.as_ref()
    }

    /// Answer actual independent product selections after their Build has run.
    /// Only component descriptions may join: source, purpose, bindings, generated
    /// bytes and execution inputs remain those the admitted activation consumed.
    pub fn with_independent_component_descriptions(
        mut self,
        descriptions: Vec<IndependentComponentDescription>,
    ) -> Result<Self, Vec<PackageCompilationInputError>> {
        self.inputs = self
            .inputs
            .with_independent_component_descriptions(descriptions)?;
        Ok(self)
    }

    #[doc(hidden)]
    pub fn into_continuation(
        self,
    ) -> (
        PathBuf,
        TargetProfile,
        PackageCompilationInputs,
        OptimizationRollback,
        PreparedBuild,
    ) {
        (
            self.root_path,
            self.target,
            self.inputs,
            self.rollback,
            self.prepared,
        )
    }
}
